"""Real supervised training/freeze from qualified sources; formal and bounded recipes."""
from pathlib import Path
from dataclasses import dataclass,asdict
import copy,time,random,hashlib,json,hmac,os
import numpy as np
import torch
from a4x.paths import RunDirectory
from a4x.provenance import artifact_ref,IntegrityError
from a4x.data import TrainNormalizer,validate_source_splits
from a4x.data.qualification import training_mask
from a4x.models.policies import PolicyConfig
from .posttrain import FAMILIES,save_model,load_policy,tensors

def _producer_key(create=False):
    """Local trusted application producer boundary, not hostile-host protection.

    Callers supply data/checkpoints, never signatures or a signing callback. The
    key is private to this experiment and cannot authorize legacy self-reports.
    """
    from a4x.paths import WORKSPACE
    path=WORKSPACE/'.runtime/training_producer/key'
    if any(p.is_symlink() for p in (path,*path.parents) if p.is_relative_to(WORKSPACE)):raise IntegrityError('Symlink producer storage forbidden')
    path.parent.mkdir(parents=True,exist_ok=True)
    if create and not path.exists():
        try:
            fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
            with os.fdopen(fd,'wb') as f:f.write(os.urandom(32))
        except FileExistsError:pass
    if not path.is_file() or path.is_symlink() or path.stat().st_mode&0o077:raise IntegrityError('Registered training producer unavailable')
    with os.fdopen(os.open(path,os.O_RDONLY|os.O_NOFOLLOW),'rb') as f:key=f.read()
    if len(key)!=32:raise IntegrityError('Invalid registered producer key')
    return key

def _producer_mac(evidence,create=False):
    payload={k:v for k,v in evidence.items() if k!='producer_signature'}
    return hmac.new(_producer_key(create),json.dumps(payload,sort_keys=True,separators=(',',':'),allow_nan=False).encode(),hashlib.sha256).hexdigest()

def state_digest(model):
    h=hashlib.sha256()
    for name,value in sorted(model.state_dict().items()):
        tensor=value.detach().cpu().contiguous();h.update(name.encode());h.update(str((tuple(tensor.shape),str(tensor.dtype))).encode());h.update(tensor.numpy().tobytes())
    return h.hexdigest()

def verify_pretrained(model,extra):
    from a4x.provenance import verify_artifact
    from a4x.paths import WORKSPACE
    ref=extra.get('pretraining_evidence_ref')
    if ref is None:raise IntegrityError('Actual pretraining evidence required, not Boolean flag')
    evidence=json.loads(verify_artifact(ref,[WORKSPACE]).read_text())
    if evidence.get('schema')!='a4x.trusted_training_producer.v1' or not hmac.compare_digest(str(evidence.get('producer_signature','')),_producer_mac(evidence)):
        raise IntegrityError('Unregistered training evidence; legacy/random weights are not learned pi0')
    if evidence['selected_state_digest']!=state_digest(model) or evidence['optimizer_updates']<1 or evidence['weight_change_l2']<=0 or evidence['normalizer']!=extra['normalizer']:raise IntegrityError('Pretrained weights/evidence/provenance mismatch')
    if not evidence['qualified_source_refs']:raise IntegrityError('Real qualified source lineage required')
    for source in evidence['qualified_source_refs']:
        cert=json.loads(verify_artifact(source,[WORKSPACE]).read_text())
        if cert.get('schema')!='a4x.qualified_teacher.v1' or cert.get('qualified') is not True:raise IntegrityError('Qualified producer source required')
        for key in ('source_execution','source_summary','numeric_audit'):verify_artifact(cert[key],[WORKSPACE])
    for key in ('initial','training_source'):verify_artifact(evidence[key],[WORKSPACE])
    for key in ('train_source_groups','train_source_hashes','train_model_signatures','qualified_source_refs'):
        if evidence[key]!=extra.get(key):raise IntegrityError('Signed training ancestry mismatch')
    initial,initial_extra=load_policy(evidence['initial']['path'])
    if evidence['initial_state_digest']!=state_digest(initial):raise IntegrityError('Producer initial weights changed')
    if extra.get('pretraining_scope')!=evidence['scope'] or json.dumps(extra.get('spec'),sort_keys=True)!=json.dumps(evidence['recipe'],sort_keys=True):
        raise IntegrityError('Signed training scope/recipe mismatch')
    config=asdict(model.config);initial_config=asdict(initial.config)
    family=evidence.get('family',initial_extra['family'])
    if config!=initial_config or config!=evidence.get('model_config',initial_config) or extra.get('family')!=family or family!=initial_extra['family'] or type(model) is not FAMILIES.get(family):
        raise IntegrityError('Signed training model config/family mismatch')
    if 'visual_encoder_ref' in evidence:
        encoder=evidence['visual_encoder_ref']
        if encoder is not None:verify_artifact(encoder,[WORKSPACE])
    else:
        # Existing signed numeric producers predate explicit visual metadata.
        # Their hashed initial checkpoint proves the SIM_STATE profile only.
        if not initial.config.profile.endswith('__SIM_STATE_V1'):raise IntegrityError('Legacy producer has no signed RGB identity')
        encoder=None
    if extra.get('visual_encoder_ref')!=encoder:raise IntegrityError('Signed frozen visual encoder mismatch')
    for ref in evidence.get('observation_source_refs',[]):verify_artifact(ref,[WORKSPACE])
    change=sum(float((value.detach()-dict(initial.named_parameters())[name].detach()).square().sum()) for name,value in model.named_parameters())**.5
    selected_change=evidence.get('selected_weight_change_l2')
    if selected_change is None and evidence['recipe']['selection']=='DEV_NO_VAL_FIXED_LAST':selected_change=evidence['weight_change_l2']
    if selected_change is None or change<=0 or not np.isclose(change,selected_change,rtol=1e-6,atol=1e-12):raise IntegrityError('Actual selected weights do not match producer updates')
    if evidence.get('pi0_ref'):
        parent=evidence['pi0_ref'];verify_artifact(parent,[WORKSPACE]);parent_model,parent_extra=load_policy(parent['path']);verify_pretrained(parent_model,parent_extra)
        if state_digest(parent_model)!=evidence['initial_state_digest']:raise IntegrityError('Frozen pi0 lineage differs from initial weights')
    return evidence

@dataclass
class TrainingSpec:
    updates:int=50000
    batch_size:int=64
    lr:float=1e-4
    seeds:tuple=(17,29,43,59,71)
    validation_every:int=2000
    selection:str='VAL_MIN_LOSS'
    scope:str='FORMAL_SOURCE_HELDOUT'
    def validate(self):
        if type(self.updates) is not int or self.updates<1 or type(self.batch_size) is not int or self.batch_size<1 or type(self.validation_every) is not int or self.validation_every<1:raise ValueError('Positive integral training recipe')
        if isinstance(self.lr,bool) or not np.isfinite(self.lr) or self.lr<=0 or not self.seeds or any(type(s) is not int for s in self.seeds):raise ValueError('Training seed/lr recipe')
        if self.selection not in ('VAL_MIN_LOSS','DEV_NO_VAL_FIXED_LAST'):raise ValueError('Unregistered checkpoint selection')
        if self.selection=='DEV_NO_VAL_FIXED_LAST' and self.scope!='DEVELOPMENT_IN_SAMPLE':raise ValueError('No-val selection cannot be formal')
        return self

def restore_normalizer(receipt):
    from a4x.data.episodes import physical_array
    if receipt['fitted_split']!='train':raise IntegrityError('Normalizer must originate train')
    result=TrainNormalizer();result.sources=receipt['source_group_ids'];result.statistics={k:(physical_array(v['mean'],'normalizer mean'),physical_array(v['std'],'normalizer std')) for k,v in receipt['statistics'].items()}
    if any(np.any(std<=0) for mean,std in result.statistics.values()):raise IntegrityError('Normalizer positive scales')
    return result

def validate_inputs(train,val,spec):
    if not train:raise ValueError('TRAIN_SOURCES_REQUIRED')
    for e in train+val:
        e.validate()
        if not training_mask(e).any():raise ValueError('INDEPENDENTLY_QUALIFIED_ACTIONS_REQUIRED')
    validate_source_splits([e.manifest for e in train+val])
    if any(e.manifest['split']!='train' for e in train) or any(e.manifest['split']!='val' for e in val):raise ValueError('Train/val roles')
    if spec.selection=='VAL_MIN_LOSS' and not val:raise ValueError('SOURCE_HELDOUT_VALIDATION_REQUIRED')
    if spec.selection=='DEV_NO_VAL_FIXED_LAST' and val:raise ValueError('Fixed-last no-val recipe cannot select from val')
    layout=train[0]
    keys=('action_profile','observation_profile','data_line')
    if any(any(e.manifest[k]!=layout.manifest[k] for k in keys) or e.observations.shape[1]!=layout.observations.shape[1] or e.actions.shape[1]!=layout.actions.shape[1] for e in train+val):raise ValueError('Shared source action/observation layouts')
    return layout

def _check_ancestry(extra,validation):
    """All learned ancestry matters, even sources absent from frozen normalizer."""
    for episode in validation:
        manifest=episode.manifest
        hashes={manifest['paired_source_hash']}
        for key in ('source_ref','execution_ref','capture_ref'):
            if manifest.get(key):hashes.add(manifest[key]['sha256'])
        cert=json.loads(Path(manifest['teacher_qualification_ref']['path']).read_text())
        if manifest['source_group_id'] in extra.get('train_source_groups',[]) or hashes&set(extra.get('train_source_hashes',[])) or cert['model_signature'] in extra.get('train_model_signatures',[]):
            raise IntegrityError('Complete learned ancestry leaks held-out validation')

def qualified_tensors(episodes,normalizer):
    from a4x.data import future_windows
    result=tensors(episodes,normalizer);result['action_mask']=torch.from_numpy(np.concatenate([future_windows(e)['training_mask'] for e in episodes]))
    return result

def train_one(train,val,run_dir,family,config,spec,seed,pi0=None,normalizer=None):
    spec.validate();layout=validate_inputs(train,val,spec)
    if config.profile!=layout.manifest['action_profile']+'__'+layout.manifest['observation_profile'] or config.observation_dim!=layout.observations.shape[1] or config.action_dim!=layout.actions.shape[1]:raise ValueError('Policy profile binding')
    torch.set_num_threads(2);torch.manual_seed(seed);np.random.seed(seed);random.seed(seed);writer=RunDirectory(run_dir)
    code_ref=writer.write_json('training_source_snapshot.json',{'scope':'PROJECT_TRAINER_SOURCE','files':[{'path':str(path),'sha256':artifact_ref(path)['sha256'],'text':path.read_text()} for path in [Path(__file__),Path(__file__).parents[1]/'models/policies.py',Path(__file__).parents[1]/'data/qualification.py']]})
    inherited_provenance={}
    if pi0:
        model,extra=load_policy(pi0['path']);from a4x.provenance import verify_artifact;verify_artifact(pi0,[Path.cwd()])
        if asdict(model.config)!=asdict(config) or extra.get('family')!=family:raise IntegrityError('Frozen pi0 config/family required')
        verify_pretrained(model,extra)
        inherited_provenance={key:extra.get(key,[]) for key in ('train_source_groups','train_source_hashes','train_model_signatures','qualified_source_refs')}
        if extra.get('visual_encoder_ref')!=layout.manifest.get('frozen_visual_encoder_ref'):raise IntegrityError('Pi0 visual encoder identity changed')
        normalizer=restore_normalizer(extra['normalizer'])
        if set(normalizer.sources)&{e.manifest['source_group_id'] for e in val}:raise IntegrityError('Pi0 normalization leaks held-out validation')
        _check_ancestry(extra,val)
    else:model=FAMILIES[family](config);normalizer=normalizer or TrainNormalizer().fit(train)
    initial=save_model(model,writer.path/'initial.pt',{'normalizer':normalizer.receipt(),'family':family,'initialization':'FROZEN_SUPPLIED_PI0' if pi0 else 'PRETRAINING_RANDOM_START'})
    data=qualified_tensors(train,normalizer);validation=qualified_tensors(val,normalizer) if val else None
    optimizer=torch.optim.AdamW(model.parameters(),lr=spec.lr);generator=torch.Generator().manual_seed(seed);history=[];best=float('inf');selected=None;start=time.monotonic();before={k:v.clone().detach() for k,v in model.named_parameters()}
    for update in range(spec.updates):
        indices=torch.randperm(len(data['action']),generator=generator)[:spec.batch_size];optimizer.zero_grad();loss,terms=model.loss(data['observation'][indices],data['observation_mask'][indices],data['action'][indices],data['action_mask'][indices],generator=generator);loss.backward();grad=float(torch.nn.utils.clip_grad_norm_(model.parameters(),1));optimizer.step()
        if not np.isfinite(float(loss.detach())) or not np.isfinite(grad):raise ValueError('Nonfinite actual training')
        entry={'update':update+1,'loss':float(loss.detach()),'gradient_norm':grad,**terms}
        if validation is not None and ((update+1)%spec.validation_every==0 or update+1==spec.updates):
            model.eval()
            with torch.no_grad():v,_=model.loss(validation['observation'],validation['observation_mask'],validation['action'],validation['action_mask'],generator=torch.Generator().manual_seed(seed+1))
            model.train();entry['val_loss']=float(v)
            if float(v)<best:best=float(v);selected={k:x.clone().detach() for k,x in model.state_dict().items()}
        history.append(entry)
    delta=sum(float((p.detach()-before[k]).square().sum()) for k,p in model.named_parameters())**.5
    if selected is not None:model.load_state_dict(selected)
    selected_delta=sum(float((p.detach()-before[k]).square().sum()) for k,p in model.named_parameters())**.5
    extra={'family':family,'normalizer':normalizer.receipt(),'pretraining_complete':True,'pretraining_scope':spec.scope,'train_source_groups':sorted({e.manifest['source_group_id'] for e in train}),'train_source_hashes':sorted({e.manifest['paired_source_hash'] for e in train}),'spec':asdict(spec),'seed':seed,'pi0_ref':pi0,'visual_encoder_ref':layout.manifest.get('frozen_visual_encoder_ref'),'qualified_source_refs':[e.manifest['teacher_qualification_ref'] for e in train],'train_model_signatures':sorted({__import__('json').loads(Path(e.manifest['teacher_qualification_ref']['path']).read_text())['model_signature'] for e in train})}
    for key in ('train_source_groups','train_source_hashes','train_model_signatures'):
        extra[key]=sorted(set(extra[key])|set(inherited_provenance.get(key,[])))
    extra['train_source_hashes']=sorted(set(extra['train_source_hashes'])|{e.manifest[key]['sha256'] for e in train for key in ('source_ref','execution_ref','capture_ref') if e.manifest.get(key)})
    for ref in inherited_provenance.get('qualified_source_refs',[]):
        if ref not in extra['qualified_source_refs']:extra['qualified_source_refs'].append(ref)
    evidence={'schema':'a4x.trusted_training_producer.v1','selected_state_digest':state_digest(model),'initial_state_digest':state_digest(load_policy(initial['path'])[0]),'initial':initial,'training_source':code_ref,'recipe':asdict(spec),'family':family,'model_config':asdict(config),'visual_encoder_ref':extra['visual_encoder_ref'],'optimizer':'AdamW/clip_norm_1','optimizer_updates':spec.updates,'weight_change_l2':delta,'selected_weight_change_l2':selected_delta,'normalizer':normalizer.receipt(),'scope':spec.scope,'pi0_ref':pi0,'history':history,**{key:extra[key] for key in ('train_source_groups','train_source_hashes','train_model_signatures','qualified_source_refs')}}
    evidence['observation_source_refs']=[e.manifest[key] for e in train for key in ('source_ref','rgb_rows_ref','frozen_visual_encoder_ref') if e.manifest.get(key)]
    # Numerical unit fixtures may execute gradients but cannot mint robot pi0.
    real_sources=all(json.loads(Path(ref['path']).read_text()).get('schema')=='a4x.qualified_teacher.v1' for ref in evidence['qualified_source_refs'])
    if real_sources:
        for episode in train:
            if not training_mask(episode).any():raise IntegrityError('Producer lost qualified source')
        evidence['producer_signature']=_producer_mac(evidence,create=True)
    else:evidence['schema']='a4x.numerical_fixture_training.v1'
    evidence_ref=writer.write_json('pretraining_evidence.json',evidence)
    extra['pretraining_evidence_ref']=evidence_ref
    checkpoint=save_model(model,writer.path/'checkpoint.pt',extra);loaded,_=load_policy(checkpoint['path']);model.eval();loaded.eval()
    with torch.no_grad():error=float((model.predict(data['observation'][:2],data['observation_mask'][:2])-loaded.predict(data['observation'][:2],data['observation_mask'][:2])).abs().max())
    report={'status':'ACTUAL_PRETRAINED_FROZEN' if pi0 is None else 'ACTUAL_POSTTRAINED','checkpoint':checkpoint,'initial':initial,'pi0':pi0,'family':family,'implementation':code_ref,'spec':asdict(spec),'seed':seed,'history':history,'normalizer':normalizer.receipt(),'weight_change_l2':delta,'reload_max_error':error,'wall_seconds':time.monotonic()-start,'source_groups':extra['train_source_groups'],'selection':spec.selection,'generalization':'NOT_ESTABLISHED' if not val else 'HELDOUT_VAL_SELECTION_NOT_TEST_PERFORMANCE','formal_50k_five_seed_protocol':spec.updates==50000 and tuple(spec.seeds)==(17,29,43,59,71) and bool(val),'physical_performance':'NOT_EVALUATED'}
    writer.write_json('training_receipt.json',report);return report

def pretrain(train,val,run_dir,family='ACT',config=None,spec=None):
    spec=(spec or TrainingSpec()).validate();layout=validate_inputs(train,val,spec);config=config or PolicyConfig(observation_dim=layout.observations.shape[1],action_dim=layout.actions.shape[1],profile=layout.manifest['action_profile']+'__'+layout.manifest['observation_profile']);writer=RunDirectory(run_dir);reports={}
    for seed in spec.seeds:reports[str(seed)]=train_one(train,val,writer.path/str(seed),family,config,spec,seed)
    writer.write_json('pretrain_receipt.json',reports);return reports

def posttrain_matched(arms,val,pi0_ref,run_dir,spec=None,equal_sources=True):
    spec=(spec or TrainingSpec()).validate();model,extra=load_policy(pi0_ref['path']);writer=RunDirectory(run_dir);source_sets=[{e.manifest['source_group_id'] for e in rows} for rows in arms.values()]
    if equal_sources and any(s!=source_sets[0] for s in source_sets):raise ValueError('Equal-source matched recipe requires identical capture-group sets')
    reports={}
    for name,rows in arms.items():
        if Path(name).name!=name or name in ('','..','.'):raise ValueError('Safe arm ID')
        if len(spec.seeds)==1:reports[name]=train_one(rows,val,writer.path/name,extra['family'],model.config,spec,spec.seeds[0],pi0=pi0_ref)
        else:
            seed_writer=RunDirectory(writer.path/name);reports[name]={str(seed):train_one(rows,val,seed_writer.path/str(seed),extra['family'],model.config,spec,seed,pi0=pi0_ref) for seed in spec.seeds}
    flat=list(reports.values()) if len(spec.seeds)==1 else [r for values in reports.values() for r in values.values()]
    if len({r['initial']['sha256'] for r in flat})!=1:raise IntegrityError('Matched arms do not share byte-identical pi0')
    writer.write_json('posttrain_receipt.json',{'reports':reports,'equal_source_groups':equal_sources,'same_initial_sha':flat[0]['initial']['sha256'],'matched_updates':spec.updates});return reports

"""Project ACT CVAE and action-conditioned diffusion; no upstream parity claim."""
from dataclasses import dataclass,asdict
import math
import torch
from torch import nn

@dataclass
class PolicyConfig:
    observation_dim:int=107
    action_dim:int=6
    chunk:int=32
    history:int=2
    hidden:int=256
    heads:int=8
    encoder_layers:int=4
    decoder_layers:int=4
    latent_dim:int=32
    kl_weight:float=10.
    dropout:float=.1
    diffusion_steps:int=100
    sampling_steps:int=16
    profile:str='SO101_NAMED_Q_RAD__SIM_STATE_V1'

def clean(values,mask):
    if not values.is_floating_point() or mask.dtype!=torch.bool or values.shape!=mask.shape or not torch.isfinite(values[mask]).all():raise ValueError('Finite active components / Boolean mask required')
    return torch.where(mask,values,0.)

class ObservationEncoder(nn.Module):
    def __init__(self,c):
        super().__init__();self.config=c;self.project=nn.Linear(2*c.observation_dim,c.hidden);self.position=nn.Parameter(torch.randn(1,c.history,c.hidden)*.02);self.null=nn.Parameter(torch.zeros(1,1,c.hidden))
    def forward(self,obs,mask):
        c=self.config
        if obs.ndim!=3 or obs.shape[1:]!=(c.history,c.observation_dim):raise ValueError('Observation history layout')
        values=clean(obs,mask);memory=self.project(torch.cat((values,mask.to(obs.dtype)),-1))+self.position
        return torch.cat((self.null.expand(len(obs),-1,-1),memory),1),torch.cat((torch.zeros((len(obs),1),dtype=torch.bool,device=obs.device),~mask.any(-1)),1)

class ACTPolicy(nn.Module):
    family='ACT_PROJECT_CVAE'
    output_space='NORMALIZED_ACTION_NOT_EXECUTABLE'
    def __init__(self,config=None):
        super().__init__();c=self.config=config or PolicyConfig()
        if c.hidden%c.heads or c.chunk!=32 or c.history!=2 or c.latent_dim!=32:raise ValueError('Registered ACT dimensions')
        self.observation=ObservationEncoder(c);self.actions=nn.Linear(c.action_dim*2,c.hidden);self.cls=nn.Parameter(torch.zeros(1,1,c.hidden));self.posterior_position=nn.Parameter(torch.randn(1,1+c.history+c.chunk,c.hidden)*.02)
        enc=nn.TransformerEncoderLayer(c.hidden,c.heads,c.hidden*4,c.dropout,batch_first=True,norm_first=True)
        self.encoder=nn.TransformerEncoder(enc,c.encoder_layers,norm=nn.LayerNorm(c.hidden));self.posterior=nn.TransformerEncoder(enc,c.encoder_layers,norm=nn.LayerNorm(c.hidden));self.mean=nn.Linear(c.hidden,c.latent_dim);self.logvar=nn.Linear(c.hidden,c.latent_dim);self.latent=nn.Linear(c.latent_dim,c.hidden)
        decoder=nn.TransformerDecoderLayer(c.hidden,c.heads,c.hidden*4,c.dropout,batch_first=True,norm_first=True)
        self.decoder=nn.TransformerDecoder(decoder,c.decoder_layers,norm=nn.LayerNorm(c.hidden));self.query=nn.Parameter(torch.randn(1,c.chunk,c.hidden)*.02);self.output=nn.Linear(c.hidden,c.action_dim)
    def forward(self,obs,observation_mask,target=None,action_mask=None,generator=None):
        c=self.config;memory,pm=self.observation(obs,observation_mask);mu=logvar=None
        if target is not None:
            if target.shape!=(len(obs),c.chunk,c.action_dim) or action_mask is None:raise ValueError('Action target layout')
            target=clean(target,action_mask);actiontokens=self.actions(torch.cat((target,action_mask.to(target.dtype)),-1))
            tokens=torch.cat((self.cls.expand(len(obs),-1,-1),memory[:,1:],actiontokens),1)+self.posterior_position
            padding=torch.cat((torch.zeros((len(obs),1),dtype=torch.bool,device=obs.device),pm[:,1:],~action_mask.any(-1)),1)
            encoded=self.posterior(tokens,src_key_padding_mask=padding)[:,0];mu=self.mean(encoded);logvar=self.logvar(encoded).clamp(-20,20)
            noise=torch.randn(mu.shape,device=mu.device,generator=generator);z=mu+(.5*logvar).exp()*noise
        else:z=obs.new_zeros((len(obs),c.latent_dim))
        memory=torch.cat((self.latent(z)[:,None],memory),1);padding=torch.cat((torch.zeros((len(obs),1),device=obs.device,dtype=torch.bool),pm),1)
        memory=self.encoder(memory,src_key_padding_mask=padding)
        prediction=self.output(self.decoder(self.query.expand(len(obs),-1,-1),memory,memory_key_padding_mask=padding))
        return prediction,mu,logvar
    def loss(self,obs,observation_mask,target,action_mask,generator=None):
        target=clean(target,action_mask);pred,mu,logvar=self(obs,observation_mask,target,action_mask,generator)
        count=action_mask.sum();l1=(torch.where(action_mask,(pred-target).abs(),0.)).sum()/count.clamp_min(1)
        active=action_mask.any(dim=(1,2));klper=-.5*(1+logvar-mu.square()-logvar.exp()).sum(-1);kl=torch.where(active,klper,0.).sum()/active.sum().clamp_min(1)
        return l1+self.config.kl_weight*kl,{'action_l1':float(l1.detach()),'kl':float(kl.detach()),'action_denominator':int(count),'identity':'ACT_PROJECT_CVAE_NOT_OFFICIAL_DEMO_REPRODUCTION'}
    @torch.no_grad()
    def predict(self,obs,mask):
        was=self.training;self.eval()
        try:return self(obs,mask)[0]
        finally:self.train(was)

class DiffusionPolicy(nn.Module):
    family='DIFFUSION_POLICY_PROJECT_ACTION_TRANSFORMER'
    output_space='NORMALIZED_ACTION_NOT_EXECUTABLE'
    def __init__(self,config=None):
        super().__init__();c=self.config=config or PolicyConfig()
        if c.hidden%c.heads or c.hidden%2:raise ValueError('Diffusion hidden/head layout')
        self.observation=ObservationEncoder(c);self.input=nn.Linear(c.action_dim*2,c.hidden);self.position=nn.Parameter(torch.randn(1,c.chunk,c.hidden)*.02)
