"""Reviewed numeric teacher compiler. Flags never replace frozen independent replay."""
from pathlib import Path
import json,subprocess,os,uuid
import numpy as np
from a4x.paths import WORKSPACE,RunDirectory
from a4x.provenance import artifact_ref,verify_artifact,IntegrityError
from .episodes import execution_episode

SNAPSHOT=WORKSPACE/'backups/F2b_validator_fixed_20261005T134912_816871/source/src'
REVIEW=WORKSPACE/'reviews/REVIEW_F2B.md'
INVENTORY=WORKSPACE/'runs/implementation_20261005/review_F2B_final_20261006T0030/reviewed_source_hashes.json'
_REPLAY_CACHE={}
GATE_SHA='73634a25a197dd9dd0518968187442a052ab9d6f824e04a4622604aee7daf7a9'

def reviewed_recipe():
    gate=artifact_ref(SNAPSHOT/'a4x/sim/gates.py');review=artifact_ref(REVIEW);inventory=artifact_ref(INVENTORY)
    if gate['sha256']!=GATE_SHA or 'ACCEPTED for tested SO101 fixed-scene' not in REVIEW.read_text():raise IntegrityError('Independent numerical review unavailable/mismatched')
    entries=json.loads(INVENTORY.read_text())['production']
    for entry in entries:
        if entry['path'].startswith('src/'):
            path=SNAPSHOT/Path(entry['path']).relative_to('src')
            if not path.is_file() or artifact_ref(path)['sha256']!=entry['sha256']:raise IntegrityError('Reviewed validator dependency mismatch')
    return {'gate':gate,'review':review,'inventory':inventory,'scope':'SIM_MODEL_REPLAY_500HZ_ESTIMATED_ASSET'}

def recompute(execution_ref,summary_ref,expected_signature,output):
    roots=[WORKSPACE];verify_artifact(execution_ref,roots);verify_artifact(summary_ref,roots);recipe=reviewed_recipe()
    writer=RunDirectory(output)
    request=writer.write_json('request.json',{'execution':execution_ref,'summary':summary_ref,'expected_signature':expected_signature,'recipe':recipe})
    script="""import json,sys;from pathlib import Path;from a4x.sim.gates import audit_artifact
r=json.loads(Path(sys.argv[1]).read_text());result=audit_artifact(r['execution'],r['summary'],[sys.argv[3]],r['expected_signature'],model_root=sys.argv[3]);Path(sys.argv[2]).write_text(json.dumps(result,indent=2))"""
    from a4x.workers.runtime import local_environment
    env=local_environment(cache_root=writer.path/'.runtime');env['PYTHONPATH']=str(SNAPSHOT)
    target=writer.path/'numeric_audit.json';proc=subprocess.run([str(WORKSPACE/'.venv-runtime/bin/python'),'-B','-c',script,request['path'],str(target),str(WORKSPACE)],cwd=WORKSPACE,env=env,capture_output=True,text=True,timeout=180)
    writer.write_json('audit_process.json',{'exit_code':proc.returncode,'stdout':proc.stdout,'stderr':proc.stderr,'scope':'REAL_FROZEN_NUMERIC_REPLAY'})
    if proc.returncode or not target.is_file():raise IntegrityError('Frozen numeric replay failed')
    return json.loads(target.read_text()),artifact_ref(target),recipe

def compile_teacher(execution_ref,summary_ref,run_dir,source_group,source_episode,split='train'):
    record=json.loads(verify_artifact(execution_ref,[WORKSPACE]).read_text());writer=RunDirectory(run_dir)
    audit,audit_ref,recipe=recompute(execution_ref,summary_ref,record['model_signature'],writer.path/'replay')
    qualified=audit['status']=='PASS' and audit['physical_qualification']['status']=='PASS' and audit['task_predicates'].get('satisfied') is True
    manifest=dict(runtime_schema='a4x.data.episode.v1',source_ref=execution_ref,execution_ref=execution_ref,source_group_id=source_group,source_episode_id=source_episode,paired_source_hash=execution_ref['sha256'],data_line='SYNTHETIC_SIM',split=split,head='execution',references=[execution_ref,summary_ref,audit_ref,*[recipe[k] for k in ('gate','review','inventory')]],parent_hashes={'execution':execution_ref['sha256'],'numeric_audit':audit_ref['sha256']})
    episode=execution_episode(record,manifest,np.eye(4),record['scene_profile']['goal_world_m'])
    certificate={'schema':'a4x.qualified_teacher.v1','source_execution':execution_ref,'source_summary':summary_ref,'model_signature':record['model_signature'],'scene_profile':record['scene_profile'],'initial_sha256':record['initial_state']['sha256'],'recipe':recipe,'numeric_audit':audit_ref,'qualified':qualified,'scope':recipe['scope'],'source_group_id':source_group,'source_episode_id':source_episode,'split':split,'command_count':len(record['commands']),'state_count':len(record['states']),'qualification_masks':[[qualified]*6 for _ in record['commands']],'hardware_certified':False,'continuous_collision_certified':False}
    cert_ref=writer.write_json('qualification.json',certificate)
    _REPLAY_CACHE[(cert_ref['sha256'],execution_ref['sha256'],audit_ref['sha256'])]=audit
    episode.manifest.update(teacher_accepted=qualified,teacher_qualification_ref=cert_ref,training_status='QUALIFIED_ESTIMATED_MODEL_TEACHER' if qualified else 'RAW_FAILED_RETAINED',references=episode.manifest['references']+[cert_ref])
    writer.write_json('compiler_receipt.json',{'qualified':qualified,'qualification':cert_ref,'numeric_audit':audit_ref,'teacher_sources':1,'accepted_rows':len(record['commands']) if qualified else 0,'raw_rows':len(record['commands']),'source_group_id':source_group,'scope':recipe['scope']})
    return episode

def training_mask(episode):
    """Readback trusted compiler binding + immutable replay/review; no Boolean authority."""
    ref=episode.manifest.get('teacher_qualification_ref')
    if ref is None:return np.zeros_like(episode.action_mask)
    from .episodes import validate_episode_provenance
    validate_episode_provenance(episode,[WORKSPACE])
    cert=json.loads(verify_artifact(ref,[WORKSPACE]).read_text());recipe=reviewed_recipe()
    for key in ('gate','review','inventory'):
        if cert['recipe'][key]!=recipe[key]:raise IntegrityError('Qualification review/version differs')
    for key in ('source_group_id','source_episode_id','split'):
        if cert[key]!=episode.manifest[key]:raise IntegrityError('Qualification source/split binding')
    if cert['source_execution']!=episode.manifest.get('execution_ref',episode.manifest['source_ref']):raise IntegrityError('Teacher source changed')
    record=json.loads(verify_artifact(cert['source_execution'],[WORKSPACE]).read_text())
    # The compiler currently supports the actual fixed synthetic world frame only.
    # A raw clock experiment is not the clock certified by this teacher recipe.
    if not np.array_equal(episode.source_time,np.asarray([s['time_s'] for s in record['states'][:-1]])):
        raise IntegrityError('Qualified source clock differs from actual capture')
    if not np.array_equal(episode.manifest['world_from_base'],np.eye(4)) or not np.array_equal(episode.manifest['goal_world'],record['scene_profile']['goal_world_m']):
        raise IntegrityError('Qualified registration/task goal differs from frozen source')
    if cert['model_signature']!=record['model_signature'] or cert['initial_sha256']!=record['initial_state']['sha256'] or cert['scene_profile']!=record['scene_profile']:raise IntegrityError('Teacher model/initial/task/controller changed')
    verify_artifact(cert['numeric_audit'],[WORKSPACE])
    key=(ref['sha256'],cert['source_execution']['sha256'],cert['numeric_audit']['sha256'])
    if key not in _REPLAY_CACHE:
        computed,_,_=recompute(cert['source_execution'],cert['source_summary'],cert['model_signature'],WORKSPACE/'.runtime/qualification_checks'/str(uuid.uuid4()))
        _REPLAY_CACHE[key]=computed
    audit=_REPLAY_CACHE[key]
    valid=cert['qualified'] is True and audit['status']=='PASS' and audit['physical_qualification']['status']=='PASS' and audit['task_predicates'].get('satisfied') is True
    masks=np.asarray(cert['qualification_masks'])
    if masks.dtype!=bool or masks.shape!=episode.action_mask.shape or np.any(masks!=valid):raise IntegrityError('Teacher mask or audit disagreement')
    if cert['command_count']!=len(episode.actions) or cert['state_count']!=len(episode.actions)+1:raise IntegrityError('Teacher denominators changed')
    return masks&episode.action_mask
